        }
        .hero {
            background: linear-gradient(rgba(44, 62, 80, 0.7), rgba(44, 62, 80, 0.7)), url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="100%" height="100%" viewBox="0 0 800 400"><rect fill="%23e0e0e0" width="800" height="400"/><circle fill="%23cccccc" cx="200" cy="200" r="100"/><circle fill="%23cccccc" cx="600" cy="150" r="150"/></svg>');
